const coldWall = drop > slots.coldWallDrop;
const tempClause = coldWall
  ? slots.midTemperature + "−" + slots.wallTemperature + "=" + drop + ">" + slots.coldWallDrop + " cold wall"
  : slots.midTemperature + "−" + slots.wallTemperature + "=" + drop + "≤" + slots.coldWallDrop + " no cold wall";
let humidityClause;
if (slots.humidityPercent >= slots.riskHumidity && slots.humidityPercent >= slots.humidityLow && slots.humidityPercent <= slots.humidityHigh) {
  humidityClause = slots.humidityPercent + "% is inside the " + slots.humidityLow + "–" + slots.humidityHigh + "% target";
} else if (slots.humidityPercent >= slots.riskHumidity) {
  humidityClause = slots.humidityPercent + "% is above the " + slots.humidityLow + "–" + slots.humidityHigh + "% target and has " + slots.riskFactor + "×" + slots.riskHumidity + "% condensation";
} else if (slots.humidityPercent < slots.humidityLow) {
  humidityClause = slots.humidityPercent + "% is below the " + slots.humidityLow + "–" + slots.humidityHigh + "% target";
} else {
  humidityClause = slots.humidityPercent + "% is outside the " + slots.humidityLow + "–" + slots.humidityHigh + "% target";
}
let actClause;
if (slots.tiltHours >= slots.tiltLimit) {
  actClause = slots.tiltHours + " h is ≥ " + slots.tiltLimit + " h → the radiator must be off";
} else if (slots.radiatorOn) {
  actClause = slots.radiatorOn
    ? "The radiator must be off (already on)."
    : "The radiator must be off (not already on).";
} else {
  actClause = "The radiator may be left on.";
}
